      for (const id of [skipped, simulated, byo, early, excludedWorkspace]) assert.deepEqual(await signals('workspace', id), [], id);
      assert.ok(statements.some(text => /CASE WHEN NOT[\s\S]*card_fingerprint END/.test(text)));
