      const every = ok(await local('POST', '/v1/api-keys', { name: 'Every address', access: { type: 'addresses' } }), 201);
      error(await change(every.id, { access: { removeAddressIds: [first.id] } }), 422, 'ADDRESS_SCOPE_REQUIRED');
